/* M611 – La préparation de commandes. a[0] = bonne réponse. */
const HS_PC = "Hors support · complément (non traité dans les leçons)";
window.OBJ = [
/* ============ 1 · h1.1 SUPPORTS ============ */
{code:"h1.1", t:"Supports papier et numériques", g:"h1.1 Je compare les moyens conventionnels (papier) et numériques (SMD, Pick by voice, etc.) dans la préparation des commandes en termes de rentabilité, d’ergonomie et de risque d’erreur. (C2)", col:"teal", ic:"scan",
ch:[
{k:"qcm",q:"Qu’est-ce que la préparation de commandes (picking) ?",a:["Rassembler des marchandises selon des ordres précis","Ranger les marchandises reçues à leur emplacement","Compter tout le stock lors de l’inventaire annuel","Charger les camions selon un plan de chargement"],ex:"Pour la production interne ou des clients externes.",ref:"Leçon 11.1"},
{k:"multi",q:"Quelles informations une liste de prélèvement doit-elle impérativement comporter ?",good:["Le numéro d’article","La désignation","L’adresse de stockage","La quantité à prélever"],bad:["Le prix d’achat de l’article","Le nom du fournisseur"],ex:"Quatre informations indispensables.",ref:"Leçon 11.1.1"},
{k:"match",q:"Associez chaque terme à sa définition.",p:[["Commissionnement","Action de préparer la commande"],["Préparateur de commandes","Opérateur qui exécute la tâche"],["Liste de prélèvement","Document regroupant les informations"]],ex:"Termes techniques.",ref:"Leçon 11.1.1"},
{k:"case",s:"Un préparateur oublie une pièce nécessaire à un kit d’assemblage destiné à la production.",q:"Quelle conséquence est la plus probable ?",a:["La chaîne de production peut s’arrêter et la livraison être retardée","Aucune, car la production commande toujours chaque pièce en double","La pièce sera simplement ajoutée au prochain inventaire annuel","Le client final recevra automatiquement une remise de prix"],ex:"Une mauvaise préparation impacte directement la production.",ref:"Leçon 11.1"},
{k:"qcm",q:"Comment les ordres sont-ils transmis en préparation hors ligne ?",a:["Sur des listes papier emportées dans l’entrepôt","Par un casque vocal relié au système informatique","Par des écrans lumineux fixés sur les rayonnages","Par un terminal mobile connecté en temps réel"],ex:"Transmission papier.",ref:"Leçon 11.3.1.2"},
{k:"multi",q:"Quels sont les avantages de la transmission papier ?",good:["Aucune technologie nécessaire","Facile à mettre en place dans un petit entrepôt"],bad:["Mise à jour du stock en temps réel","Modification facile d’une commande en cours"],ex:"Avantages de la liste papier.",ref:"Leçon 11.3.1.2"},
{k:"multi",q:"Quels sont les inconvénients de la transmission papier ?",good:["Risque d’erreurs de lecture ou d’écriture","Commande difficile à modifier en cours","Mise à jour du stock manuelle ou différée"],bad:["Coût élevé des équipements","Besoin d’une connexion informatique stable"],ex:"Inconvénients de la liste papier.",ref:"Leçon 11.3.1.2"},
{k:"match",q:"Associez chaque système numérique à son support.",p:[["Pick-by-Voice","Casque vocal"],["Pick-by-Light","Écrans lumineux sur les rayons"],["Pick-by-Scan","Lecteur de codes-barres"],["Pick-by-RFID","Puce détectée à distance"]],ex:"Transmission en ligne.",ref:"Leçon 11.3.1.2"},
{k:"sort",q:"Classez ces caractéristiques.",c:["Papier (hors ligne)","Numérique (en ligne)"],it:[["Aucune infrastructure nécessaire",0],["Erreurs de lecture fréquentes",0],["Stock mis à jour plus tard",0],["Stock mis à jour en temps réel",1],["Commande modifiable en cours",1],["Coût d’équipement et de formation",1]],ex:"Comparaison papier / numérique.",ref:"Leçon 11.3.1.2"},
{k:"tf",q:"La transmission numérique des ordres nécessite une connexion informatique stable.",v:true,ex:"Inconvénient du numérique, avec le coût.",ref:"Leçon 11.3.1.2"},
{k:"tf",q:"Avec une liste papier, il est facile de modifier une commande pendant sa préparation.",v:false,ex:"C’est un inconvénient du papier.",ref:"Leçon 11.3.1.2"},
{k:"qcm",q:"Quel est l’avantage principal du Pick-by-RFID ?",a:["Aucune manipulation ni visée directe n’est nécessaire","Il ne nécessite aucune étiquette sur les articles","Il fonctionne sans aucun système informatique","Il remplace complètement le préparateur humain"],ex:"Détection même à distance ou à travers l’emballage.",ref:"Leçon 11.3.1.2"},
{k:"case",s:"Un préparateur passe un bac rempli d’articles devant un capteur, et le système détecte aussitôt son contenu.",q:"Quelle technologie est utilisée ?",a:["Le Pick-by-RFID","Le Pick-by-Light","La liste papier","Le Pick-by-Voice"],ex:"Puce RFID détectée sans visée.",ref:"Leçon 11.3.1.2"},
{k:"case",s:"Une PME de 200 m² prépare une dizaine de commandes par jour et n’a pas de budget informatique.",q:"Quel support lui conseillez-vous ?",a:["La liste papier, simple et sans investissement","Un système Pick-by-Light sur tous les rayonnages","Un robot de prélèvement entièrement automatique","Un trieur cross-belt relié à un WMS complet"],ex:"Le papier est facile à mettre en place dans un petit entrepôt.",ref:"Leçon 11.3.1.2"},
{k:"case",s:"Un grand entrepôt e-commerce constate beaucoup d’erreurs de lecture sur ses listes papier.",q:"Quelle mesure réduit le mieux ces erreurs ?",a:["Passer à un système numérique qui identifie les articles","Imprimer les listes papier en caractères plus petits","Supprimer les adresses de stockage sur les listes","Demander aux préparateurs de travailler plus vite"],ex:"Le numérique identifie les articles automatiquement.",ref:"Leçons 11.2.4 et 11.3.1.2"},
{k:"case",s:"Un préparateur doit garder les deux mains libres pour manipuler des cartons lourds tout en recevant ses instructions.",q:"Quel système est le plus ergonomique ?",a:["Le Pick-by-Voice, avec un casque","La liste papier, tenue à la main","Le terminal mobile tenu à la main","Le Pick-by-Scan avec un pistolet"],ex:"Instructions vocales, mains libres.",ref:"Leçon 11.3.1.2"},
{k:"case",s:"Une direction hésite à remplacer ses listes papier par des terminaux mobiles.",q:"Quel argument de rentabilité avancez-vous ?",a:["Moins d’erreurs et un stock à jour, malgré un coût de départ","Aucun coût de départ, car les terminaux sont toujours gratuits","Plus besoin de former le personnel au nouveau système","Plus besoin d’adresses de stockage dans l’entrepôt"],ex:"Investissement contre réduction des erreurs et des coûts opérationnels.",ref:"Leçon 11.3.1.2"},
{k:"qcm",q:"Quand une commande est saisie, que fait aussitôt le système ?",a:["Il réserve les articles et génère un ordre de préparation","Il envoie directement la facture au transporteur","Il commande automatiquement les articles au fournisseur","Il supprime les articles du stock sans contrôle"],ex:"Réservation et ordre de préparation.",ref:"Leçon 11.3.1.1"},
{k:"multi",q:"Par quels canaux une commande peut-elle arriver ?",good:["Internet","Téléphone","Courrier, fax ou e-mail"],bad:["Par la balance de pesée","Par le trieur à plateaux"],ex:"Canaux de commande.",ref:"Leçon 11.3.1.1"},
{k:"order",q:"Remettez dans l’ordre le flux d’informations d’une commande.",a:["Le client passe commande","Les articles sont réservés dans le stock","L’ordre de préparation est transmis au préparateur","Le prélèvement est confirmé (quittance)","Le stock est mis à jour"],ex:"Du passage de commande à la mise à jour du stock.",ref:"Leçon 11.3.1"},
{k:"case",s:"Un client passe une commande urgente à 10 h et le préparateur la reçoit à 10 h 01.",q:"De quel type de traitement s’agit-il ?",a:["Le traitement en temps réel","Le traitement par lots de l’après-midi","La préparation orientée article","Le contrôle par échantillonnage"],ex:"Traitement immédiat.",ref:"Leçon 11.3.1.1"},
{k:"case",s:"À 14 h, l’entrepôt génère en une seule fois 20 ordres de préparation pour les commandes du matin.",q:"De quel type de traitement s’agit-il ?",a:["Le traitement par lots","Le traitement en temps réel","La quittance automatique","Le Pick-by-RFID à distance"],ex:"Commandes regroupées.",ref:"Leçon 11.3.1.1"},
{k:"fill",q:"Avec la quittance ___, la mise à jour du stock est instantanée.",a:["automatique","manuelle","différée","papier"],ex:"La quittance manuelle donne une mise à jour différée.",ref:"Leçon 11.3.1.3"},
{k:"odd",q:"Trouvez l’intrus parmi ces supports numériques de préparation.",a:["La liste papier cochée au stylo","Le terminal mobile","Le casque Pick-by-Voice","Les écrans Pick-by-Light"],ex:"La liste papier est un support conventionnel.",ref:"Leçon 11.3.1.2"},
{k:"tf",q:"La préparation sans papier fait partie des solutions pour éviter les erreurs.",v:true,ex:"Avec des outils numériques.",ref:"Leçon 11.2.4"},
{k:"case",s:"Un préparateur coche au stylo chaque article prélevé, et les quantités sont saisies dans le système en fin de journée.",q:"Quel risque cela présente-t-il ?",a:["Le stock affiché est faux pendant toute la journée","Le stock est toujours exact en temps réel","Les articles ne peuvent plus jamais être prélevés","La commande est automatiquement annulée le soir"],ex:"Quittance manuelle : mise à jour différée.",ref:"Leçon 11.3.1.3"}
]},
/* ============ 2 · h1.2 h1.6 h1.7 ============ */
{code:"h1.2·h1.6·h1.7", t:"Partielles, ERP et réapprovisionnement", g:"h1.2 J’explique l’impact des préparations des commandes partielles sur le temps d’exécution d’une préparation de commandes. (C2) · h1.6 J’explique la procédure de correction des quantités dans l’ERP de l’entreprise après la préparation de commandes. (C2) · h1.7 J’explique comment le réapprovisionnement garantit la disponibilité des marchandises dans l’entrepôt de préparation des commandes sur la base du contrôle des quantités. (C2)", col:"indigo", ic:"cycle",
ch:[
{k:"qcm",q:"Qu’est-ce qu’une préparation de commande partielle ?",a:["Une commande divisée en parties préparées séparément puis regroupées","Une commande préparée seulement à moitié puis annulée par le client","Une commande dont on ne prépare que les articles les plus chers","Une commande préparée uniquement pendant la pause de midi"],ex:"Préparation en parallèle : parties traitées séparément, puis regroupement.",ref:"Leçon 11.3.3.3"},
{k:"multi",q:"Quelles étapes supplémentaires une commande partielle impose-t-elle ?",good:["Le regroupement des parties","Le suivi de chaque partie","Le contrôle de la commande reconstituée"],bad:["La suppression du contrôle final","L’annulation des autres commandes"],ex:"Étapes de gestion des partielles.",ref:"Leçon 11.3.3.3 · "+HS_PC},
{k:"case",s:"Une commande de 3 articles se trouve entièrement dans une seule zone de l’entrepôt.",q:"Est-il utile de la diviser en commandes partielles ?",a:["Non, le regroupement ajouterait du temps inutile","Oui, toute commande doit être divisée en parties","Oui, car diviser supprime toujours tout contrôle","Non, car une commande partielle est interdite"],ex:"Les partielles ajoutent regroupement et suivi.",ref:"Leçon 11.3.3 · "+HS_PC},
{k:"case",s:"Une commande de 120 lignes concerne trois zones éloignées ; trois préparateurs la traitent en même temps.",q:"Quel est l’intérêt de cette préparation partielle ?",a:["Réduire le délai total grâce au travail simultané","Supprimer le regroupement des articles à la fin","Éviter tout contrôle de la marchandise prélevée","Augmenter le nombre de trajets de chaque préparateur"],ex:"La préparation en parallèle réduit les délais des commandes à nombreuses lignes.",ref:"Leçon 11.3.3.3"},
{k:"case",s:"Une partie d’une commande attend au poste de regroupement, car la troisième zone n’a pas terminé son prélèvement.",q:"Quel est l’effet sur le temps d’exécution ?",a:["La commande attend la partie la plus lente","Le temps diminue, car la commande est déjà prête","Aucun effet, les parties partent séparément","La commande est expédiée sans la partie manquante"],ex:"Le regroupement dépend de la dernière partie terminée.",ref:"Leçon 11.3.3.3 · "+HS_PC},
{k:"tf",q:"Une commande partielle peut augmenter le temps total d’exécution à cause du regroupement et du suivi.",v:true,ex:"Étapes supplémentaires.",ref:HS_PC},
{k:"sort",q:"Classez ces situations.",c:["Commande complète conseillée","Commande partielle conseillée"],it:[["Peu d’articles dans une seule zone",0],["Commande urgente de 2 lignes",0],["Commande de 150 lignes sur 4 zones",1],["Articles répartis dans des zones éloignées",1]],ex:"La partielle se justifie pour les commandes longues réparties sur plusieurs zones.",ref:"Leçon 11.3.3.3"},
{k:"qcm",q:"Que signifie ERP ?",a:["Enterprise Resource Planning","Entrepôt de Réserve Principal","European Reception Process","Électronique de Relevé des Positions"],ex:"Progiciel de gestion intégré.",ref:HS_PC},
{k:"qcm",q:"Quel rôle l’ERP joue-t-il dans la gestion des stocks ?",a:["Il enregistre les mouvements et indique le stock disponible","Il déplace physiquement les palettes dans l’entrepôt","Il remplace les adresses de stockage par des couleurs","Il fabrique les étiquettes de transport des camions"],ex:"Les données de l’ERP servent au stock et à la planification.",ref:HS_PC},
{k:"case",s:"Le système indique 12 pièces à l’emplacement, mais le préparateur n’en trouve que 9.",q:"Que doit-il faire ?",a:["Signaler l’écart pour une correction de quantité dans l’ERP","Prélever 9 pièces et ne rien dire à personne","Modifier lui-même l’adresse de stockage de l’article","Ajouter 3 pièces d’un autre article ressemblant"],ex:"Un écart doit être enregistré (quantité manquante) puis corrigé.",ref:"Leçon 11.5.4 · "+HS_PC},
{k:"order",q:"Remettez dans l’ordre une procédure de correction de quantité dans l’ERP.",a:["Constater l’écart entre le stock réel et le système","Recompter physiquement l’emplacement","Saisir la correction avec un motif dans l’ERP","Faire valider la correction par le responsable","Analyser la cause pour éviter qu’elle se reproduise"],ex:"Constat, vérification, saisie motivée, validation, analyse.",ref:HS_PC},
{k:"multi",q:"Pourquoi des corrections de quantité sont-elles nécessaires après la préparation ?",good:["Des erreurs de prélèvement ont pu se produire","Des articles ont pu être abîmés ou perdus","Une quittance a pu être oubliée"],bad:["Pour augmenter artificiellement le stock","Pour éviter tout inventaire annuel"],ex:"L’ERP doit refléter le stock réel.",ref:HS_PC},
{k:"case",s:"L’ERP affiche un stock suffisant, mais l’article est en réalité épuisé ; aucune commande au fournisseur n’est déclenchée.",q:"Quelle est la conséquence ?",a:["Une rupture de stock et des commandes non livrées","Un stock toujours exact grâce à la quittance différée","Une commande automatique de dix fois la quantité","Aucune, l’ERP ne sert pas à la planification"],ex:"L’exactitude des données de l’ERP conditionne la planification.",ref:HS_PC},
{k:"tf",q:"Avec une quittance automatique, la mise à jour du stock est instantanée.",v:true,ex:"Le système sait immédiatement que l’article a été retiré.",ref:"Leçon 11.3.1.3"},
{k:"tf",q:"Une correction de quantité dans l’ERP peut être saisie sans motif ni contrôle.",v:false,ex:"Un motif et une validation garantissent la traçabilité.",ref:HS_PC},
{k:"qcm",q:"Qu’est-ce que le réapprovisionnement en préparation de commandes ?",a:["Le remplissage des emplacements de prélèvement depuis la réserve","La livraison des commandes préparées chez les clients","Le retour des articles défectueux chez le fournisseur","Le nettoyage des allées après chaque préparation"],ex:"Il garantit la disponibilité des marchandises au poste de prélèvement.",ref:"Leçon 11.7 · "+HS_PC},
{k:"qcm",q:"Comment le contrôle des quantités permet-il de déclencher le réapprovisionnement ?",a:["Quand le stock de l’emplacement atteint un seuil minimal","Quand le préparateur a terminé sa journée de travail","Quand le client se plaint d’un retard de livraison","Une seule fois par an, lors de l’inventaire général"],ex:"Seuil minimal par emplacement.",ref:HS_PC},
{k:"match",q:"Associez chaque exemple d’entrepôt à son type de réapprovisionnement.",p:[["Réserve au-dessus du niveau de prélèvement","Réapprovisionnement manuel"],["Postes alimentés par transstockeurs","Réapprovisionnement automatique"],["Rayonnage dynamique FIFO","Remplissage manuel par l’arrière"]],ex:"Exemples de conception d’entrepôts.",ref:"Leçon 11.7"},
{k:"case",s:"Un préparateur arrive devant un emplacement vide alors que la réserve, juste au-dessus, est pleine.",q:"Qu’est-ce qui a mal fonctionné ?",a:["Le réapprovisionnement n’a pas été déclenché à temps","Le préparateur a choisi un mauvais itinéraire","Le client a commandé une trop grande quantité","Le trieur a envoyé l’article au mauvais quai"],ex:"Un réapprovisionnement insuffisant crée du temps perdu.",ref:"Leçon 11.7 · "+HS_PC},
{k:"multi",q:"Quelles sont les conséquences d’un réapprovisionnement insuffisant ?",good:["Des emplacements vides","Du temps perdu à attendre","Des commandes incomplètes"],bad:["Des allées toujours dégagées","Un stock trop important au poste"],ex:"Le réappro garantit la disponibilité.",ref:HS_PC},
{k:"case",s:"Un collègue remplit les emplacements de prélèvement bien au-delà de leur capacité, avec des cartons posés devant.",q:"Quel est le risque ?",a:["Un encombrement qui gêne le prélèvement et la sécurité","Une rupture de stock immédiate sur tous les articles","Un réapprovisionnement trop rare et insuffisant","Une diminution du nombre d’articles en réserve"],ex:"Un réapprovisionnement excessif encombre et crée des risques.",ref:HS_PC},
{k:"case",s:"Un entrepôt à très fort volume veut éviter toute attente des préparateurs devant des emplacements vides, quel que soit le coût.",q:"Quelle conception choisissez-vous ?",a:["Des postes alimentés automatiquement par transstockeurs","Un réapprovisionnement manuel une fois par semaine","Une réserve au sol, loin des postes de prélèvement","Aucun réapprovisionnement, seulement des inventaires"],ex:"Exemple 2 : disponibilité continue, investissement élevé.",ref:"Leçon 11.7"},
{k:"case",s:"Des petits articles à forte rotation sont stockés dans un rayonnage dynamique : on remplit par l’arrière, on prélève par l’avant.",q:"Quel principe est appliqué ?",a:["FIFO : premier entré, premier sorti","LIFO : dernier entré, premier sorti","Prélèvement orienté article par lots","Préparation bidimensionnelle à grande levée"],ex:"Exemple 3 : rayonnage dynamique FIFO.",ref:"Leçon 11.7"},
{k:"fill",q:"Dans l’exemple 1, la préparation se fait au niveau bas et la ___ est placée au-dessus.",a:["réserve","zone d’expédition","zone de quai","balance de pesée"],ex:"Réapprovisionnement manuel depuis le haut.",ref:"Leçon 11.7"},
{k:"odd",q:"Trouvez l’intrus parmi ces causes de corrections de quantités.",a:["Une adresse de stockage bien étiquetée","Un mauvais nombre d’articles prélevés","Une quittance oubliée","Un article abîmé retiré du stock"],ex:"Un bon étiquetage évite les écarts.",ref:"Leçon 11.2.2 · "+HS_PC},
{k:"case",s:"Votre chef vous demande pourquoi l’exactitude des quantités dans l’ERP est si importante.",q:"Que répondez-vous ?",a:["Elle permet de planifier les achats et d’éviter les ruptures","Elle sert seulement à imprimer de jolies étiquettes","Elle n’a d’intérêt que pour le service de comptabilité","Elle permet d’éviter de former les préparateurs"],ex:"Gestion des stocks et planification.",ref:HS_PC}
]},
/* ============ 3 · h1.4 AUTOMATISATION ============ */
{code:"h1.4", t:"Automatisation et trieurs", g:"h1.4 J’explique les techniques d’automatisation de la préparation des commandes et décris leur domaine d’application. (C2)", col:"violet", ic:"sorter",
ch:[
{k:"qcm",q:"Qu’est-ce qu’un trieur ?",a:["Un système automatisé qui oriente les marchandises vers leur destination","Un préparateur chargé de trier les documents avant le prélèvement","Un rayonnage statique où les articles sont classés par couleur","Un logiciel qui calcule le prix de transport des colis"],ex:"Grâce à la lecture d’un code-barres.",ref:"Leçon 11.4"},
{k:"qcm",q:"Sur quoi les trieurs s’appuient-ils pour identifier chaque article ?",a:["La lecture d’un code-barres","La couleur de l’emballage","Le poids approximatif","Le nom du préparateur"],ex:"Codes apposés dès l’entrée dans le système.",ref:"Leçon 11.4"},
{k:"match",q:"Associez chaque trieur à son principe.",p:[["Tilt tray","Plateau qui bascule dans une goulotte"],["Sliding sorter","Sabots qui poussent latéralement"],["Pop-up sorter","Rouleaux inclinés qui se soulèvent"],["Cross belt","Bandes courtes perpendiculaires"]],ex:"Types de trieurs.",ref:"Leçons 11.4.1 à 11.4.4"},
{k:"case",s:"Un aéroport doit trier des bagages volumineux vers différents vols.",q:"Quel trieur est adapté ?",a:["Le trieur à plateau inclinable (tilt tray)","Le trieur à trappes pour lettres et textiles","Le trieur à roulettes pour sachets souples","La liste papier triée à la main au quai"],ex:"Articles volumineux comme les bagages.",ref:"Leçon 11.4.1"},
{k:"case",s:"Un centre de distribution trie des caisses en plastique réutilisables à fond plat et rigide.",q:"Quel trieur convient le mieux ?",a:["Le trieur à sabots (sliding sorter)","Le trieur à trappes (split-tray)","Le trieur à plateau pour bagages","Le trieur manuel par goulotte"],ex:"Fond plat et rigide : cartons, blisters, caisses.",ref:"Leçon 11.4.2"},
{k:"case",s:"Un fabricant d’électronique veut trier de petits appareils fragiles sans les secouer.",q:"Quel trieur choisissez-vous ?",a:["Le trieur à bandes transversales (cross belt)","Le trieur à plateau inclinable qui bascule","Le trieur à trappes qui laisse tomber les articles","Le trieur à roulettes qui dévie brusquement"],ex:"Évacuation en douceur, plus délicat que la bascule.",ref:"Leçon 11.4.4"},
{k:"case",s:"Une entreprise de vente de vêtements doit trier des textiles souples non emballés.",q:"Quel trieur est adapté ?",a:["Le trieur à trappes (split-tray)","Le trieur à roulettes (pop-up)","Le trieur à sabots (sliding)","Le trieur à bandes pour bagages"],ex:"Produits légers, souples ou non emballés.",ref:"Leçon 11.4.5"},
{k:"tf",q:"Le trieur à roulettes pivotantes (pop-up) convient aux sachets et aux articles souples.",v:false,ex:"Il convient aux marchandises rigides à surface lisse.",ref:"Leçon 11.4.3"},
{k:"tf",q:"Le trieur à bandes transversales préserve mieux les produits que le trieur à bascule.",v:true,ex:"Il les évacue en douceur.",ref:"Leçon 11.4.4"},
{k:"sort",q:"Classez ces marchandises selon le trieur adapté.",c:["Trieur à trappes","Trieur à sabots"],it:[["Lettres",0],["Textiles non emballés",0],["Vêtements souples",0],["Cartons à fond plat",1],["Blisters rigides",1],["Caisses en plastique",1]],ex:"Souple et léger contre plat et rigide.",ref:"Leçons 11.4.2 et 11.4.5"},
{k:"odd",q:"Trouvez l’intrus parmi ces trieurs automatiques.",a:["La liste de prélèvement","Le tilt tray sorter","Le cross belt sorter","Le split-tray sorter"],ex:"La liste est un support d’information.",ref:"Leçon 11.4"},
{k:"fill",q:"Dans le trieur à plateau inclinable, les produits tombent dans une goulotte par ___.",a:["gravité","aspiration","aimantation","vibration"],ex:"Les plateaux basculent.",ref:"Leçon 11.4.1"},
{k:"qcm",q:"Qu’est-ce que la préparation dynamique ?",a:["La marchandise se déplace jusqu’au préparateur","Le préparateur se déplace jusqu’aux articles","Le préparateur travaille sans aucune liste","La commande est préparée par le client lui-même"],ex:"Principe « marchandise vers personne ».",ref:"Leçon 11.3.2.1"},
{k:"multi",q:"Quels sont les avantages de la préparation dynamique ?",good:["Très rapide","Moins d’efforts physiques"],bad:["Coût d’installation faible","Idéale pour les commandes spéciales urgentes"],ex:"Mais coût élevé et moins adapté aux commandes spéciales.",ref:"Leçon 11.3.2.1"},
{k:"multi",q:"Quels sont les avantages du prélèvement automatique ?",good:["Très rapide","Peu d’erreurs","Rentable à grande échelle"],bad:["Peu coûteux à installer","Adapté à tous les produits non standard"],ex:"Réservé aux produits standardisés.",ref:"Leçon 11.3.2.3"},
{k:"case",s:"Un bras robotisé prélève 50 flacons identiques dans un stock automatisé.",q:"Pourquoi l’automatisation est-elle adaptée ici ?",a:["Les produits sont standardisés en taille, poids et forme","Les produits sont tous différents et très fragiles","La commande est unique et ne se répétera jamais","Le robot est moins cher qu’un transpalette manuel"],ex:"Automatique : réservé aux produits standardisés.",ref:"Leçon 11.3.2.3"},
{k:"case",s:"Un atelier de restauration de meubles anciens prépare des pièces uniques de formes très variées.",q:"Faut-il automatiser le prélèvement ?",a:["Non, le prélèvement manuel reste plus adapté","Oui, un robot gère mieux les pièces uniques","Oui, un trieur à trappes conviendrait parfaitement","Non, car les meubles ne se préparent jamais"],ex:"Produits non standardisés : l’automatisation est peu rentable.",ref:"Leçon 11.3.2.3"},
{k:"sort",q:"Classez ces caractéristiques de l’automatisation.",c:["Avantage","Inconvénient"],it:[["Rapidité élevée",0],["Peu d’erreurs",0],["Moins d’efforts physiques",0],["Investissement élevé",1],["Peu de flexibilité pour les produits spéciaux",1],["Réservé aux produits standardisés",1]],ex:"Coûts, rapidité, flexibilité.",ref:"Leçon 11.3.2"},
{k:"case",s:"Une direction hésite à automatiser un entrepôt qui traite peu de commandes, très variées.",q:"Que lui conseillez-vous ?",a:["Rester manuel : l’investissement ne serait pas rentable","Tout automatiser : c’est rentable à n’importe quel volume","Installer un trieur pour chaque article de l’assortiment","Supprimer la préparation et livrer les palettes entières"],ex:"L’automatisation est rentable à grande échelle.",ref:"Leçons 11.3.2 et 11.7"},
{k:"qcm",q:"Qu’est-ce qu’un transstockeur dans l’exemple 2 de la leçon 11.7 ?",a:["Un engin automatique qui alimente les postes de préparation","Un préparateur qui passe d’une zone à l’autre","Un document qui transfère le stock entre deux entrepôts","Un chariot manuel pour les articles légers"],ex:"Réapprovisionnement automatique.",ref:"Leçon 11.7"},
{k:"tf",q:"Les trieurs utilisent des supports de charge et des mémoires de données mobiles.",v:true,ex:"Pour recevoir ou transmettre des données.",ref:"Leçon 11.4"},
{k:"case",s:"Dans un centre de tri postal, des milliers de lettres doivent être orientées vers leurs tournées.",q:"Quelle technique d’automatisation est la plus adaptée ?",a:["Un trieur à trappes lisant le code de chaque envoi","Un tilt tray conçu pour les bagages volumineux","Un transpalette électrique conduit à la main","Une liste papier lue par chaque facteur"],ex:"Lettres : produits légers et plats.",ref:"Leçon 11.4.5"},
{k:"multi",q:"Quelles techniques d’automatisation de la préparation de commandes connaissez-vous ?",good:["Les trieurs","Les robots de prélèvement","Les convoyeurs et navettes automatiques","Les transstockeurs"],bad:["Les listes papier","Les transpalettes manuels"],ex:"Techniques d’automatisation.",ref:"Leçons 11.3.2, 11.4 et 11.7"},
{k:"case",s:"Un trieur s’arrête : les étiquettes de plusieurs colis sont illisibles.",q:"Quelle est la cause la plus probable ?",a:["Le code-barres ne peut plus être lu par la machine","Le trieur fonctionne mieux sans aucune étiquette","Les colis sont trop légers pour être triés","Le préparateur a utilisé la méthode MOP"],ex:"Les trieurs reposent sur une étiquette lisible par machine.",ref:"Leçon 11.4"},
{k:"order",q:"Remettez dans l’ordre le passage d’un colis dans un trieur.",a:["Une étiquette à code-barres est apposée","Le colis entre dans le trieur","Le code-barres est lu","Le trieur oriente le colis vers sa destination"],ex:"Identification puis orientation.",ref:"Leçon 11.4"}
]},
/* ============ 4 · h3.1 TROIS DOMAINES ============ */
{code:"h3.1", t:"Les trois domaines du système", g:"h3.1 Je décris les trois domaines du système de préparation des commandes, à savoir le flux de matériel, le flux de données et l’organisation ; leur lien et leur effet sur la performance de préparation des commandes. (C3)", col:"coral", ic:"flows",
ch:[
{k:"multi",q:"Quels sont les trois domaines du système de préparation des commandes ?",good:["Le flux de matériel","Le flux de données (informations)","L’organisation"],bad:["Le flux financier","Le marketing"],ex:"Trois domaines liés.",ref:"Leçon 11.3"},
{k:"match",q:"Associez chaque domaine à ses composantes.",p:[["Flux de matériel","Mise à disposition, déplacement, prélèvement, transfert"],["Flux d’informations","Saisie, transmission, quittance"],["Organisation","Zones, orientation, série ou parallèle"]],ex:"Composantes principales.",ref:"Leçons 11.3.1 à 11.3.3"},
{k:"sort",q:"Classez ces éléments dans leur domaine.",c:["Flux de matériel","Flux d’informations","Organisation"],it:[["Préparation statique",0],["Transfert décentralisé",0],["Quittance automatique",1],["Traitement par lots",1],["Préparation en parallèle",2],["Secteur unique",2]],ex:"Trois domaines.",ref:"Leçon 11.3"},
{k:"order",q:"Remettez dans l’ordre les étapes du flux de matériel.",a:["Mise à disposition des marchandises","Déplacement du préparateur","Prélèvement des produits","Transfert après préparation"],ex:"Du stockage à la remise.",ref:"Leçon 11.3.2"},
{k:"qcm",q:"Qu’est-ce que la préparation statique ?",a:["Le préparateur se déplace vers les articles","La marchandise vient jusqu’au préparateur","Les articles restent toujours dans le camion","Le préparateur ne se déplace jamais de son poste"],ex:"Simple et peu coûteuse.",ref:"Leçon 11.3.2.1"},
{k:"fill",q:"Dans la préparation statique, c’est le ___ qui se déplace vers les articles.",a:["préparateur","convoyeur","transstockeur","client final"],ex:"Personne vers marchandise.",ref:"Leçon 11.3.2.1"},
{k:"case",s:"Dans un entrepôt de pièces détachées de 300 m², le préparateur va de rayon en rayon chercher chaque article.",q:"Quel mode de mise à disposition est utilisé ?",a:["La préparation statique (personne vers marchandise)","La préparation dynamique (marchandise vers personne)","Le prélèvement automatique par un robot","Le transfert décentralisé par convoyeur"],ex:"Adapté aux petits entrepôts.",ref:"Leçon 11.3.2.1"},
{k:"case",s:"Dans un entrepôt de 20 000 m², les préparateurs parcourent des kilomètres chaque jour et sont épuisés.",q:"Quelle amélioration proposez-vous ?",a:["Passer à une mise à disposition dynamique (marchandise vers personne)","Ajouter des allées supplémentaires pour allonger les trajets","Supprimer les adresses de stockage pour gagner du temps","Remplacer les terminaux mobiles par des listes papier"],ex:"Statique : trajets longs dans les grands entrepôts.",ref:"Leçons 11.3.2.1 et 11.5.2"},
{k:"qcm",q:"Qu’est-ce que le déplacement unidimensionnel ?",a:["Le préparateur circule au sol, sans monter","Le préparateur monte à différents niveaux","Le préparateur reste à un poste fixe","Le préparateur se déplace en dehors de l’entrepôt"],ex:"Transpalettes, chariots à roulettes, faible levée.",ref:"Leçon 11.3.2.2"},
{k:"case",s:"Dans un entrepôt d’électronique, certains articles sont stockés à 5 m de haut.",q:"Quel type de déplacement faut-il prévoir ?",a:["Un déplacement multidimensionnel avec un élévateur","Un déplacement unidimensionnel avec un transpalette","Aucun déplacement, les articles tomberont seuls","Un déplacement à pied avec une liste papier"],ex:"Exploitation de la hauteur.",ref:"Leçon 11.3.2.2"},
{k:"multi",q:"Quels équipements permettent un déplacement multidimensionnel ?",good:["Les nacelles élévatrices","Les convoyeurs verticaux","Les chariots à mât rétractable"],bad:["Le transpalette manuel","Le chariot à roulettes"],ex:"Accès à différents niveaux.",ref:"Leçon 11.3.2.2"},
{k:"tf",q:"Le déplacement unidimensionnel permet d’exploiter toute la hauteur de l’entrepôt.",v:false,ex:"Il perd la place en hauteur.",ref:"Leçon 11.3.2.2"},
{k:"qcm",q:"Qu’est-ce que le transfert centralisé ?",a:["Tous les produits passent par un même point de regroupement","Chaque produit part directement vers sa propre destination","Les produits restent dans la zone de prélèvement","Les produits sont livrés chez le client sans emballage"],ex:"Facile à contrôler, risque de bouchons.",ref:"Leçon 11.3.2.4"},
{k:"case",s:"Chaque commande prélevée part par tapis roulant directement vers sa palette d’expédition.",q:"Quel type de transfert est utilisé ?",a:["Le transfert décentralisé","Le transfert centralisé","La préparation statique","Le traitement par lots"],ex:"Gain de temps, moins de visibilité globale.",ref:"Leçon 11.3.2.4"},
{k:"sort",q:"Classez ces caractéristiques.",c:["Transfert centralisé","Transfert décentralisé"],it:[["Facile à contrôler",0],["Risque de bouchons",0],["Gain de temps",1],["Moins de visibilité globale",1]],ex:"Avantages et inconvénients.",ref:"Leçon 11.3.2.4"},
{k:"qcm",q:"Qu’est-ce que le prélèvement orienté article ?",a:["Prélever un article pour plusieurs commandes, puis répartir","Prélever tous les articles d’une seule commande client","Prélever uniquement les articles de la classe C","Prélever les articles dans l’ordre alphabétique"],ex:"Réduit les déplacements.",ref:"Leçon 11.3.3.2"},
{k:"case",s:"Un préparateur prélève 30 clés USB en une fois, puis les répartit dans 6 commandes au poste de tri.",q:"Quelle organisation est appliquée ?",a:["Le prélèvement orienté article","Le prélèvement orienté commande","La préparation en secteur unique","Le contrôle par échantillonnage"],ex:"Plusieurs commandes, puis répartition.",ref:"Leçon 11.3.3.2"},
{k:"case",s:"Une préparatrice prépare une commande de 5 articles, l’emballe puis l’expédie avant de commencer la suivante.",q:"Quelle organisation est appliquée ?",a:["Le prélèvement orienté commande","Le prélèvement orienté article","La préparation en parallèle","Le transfert décentralisé"],ex:"Une commande à la fois, directement prête.",ref:"Leçon 11.3.3.2"},
{k:"qcm",q:"Qu’est-ce que la préparation en série ?",a:["Les commandes sont traitées l’une après l’autre, zone par zone","Plusieurs préparateurs traitent la même commande en même temps","Les commandes sont préparées par un robot en série continue","Le client prépare lui-même sa commande en libre-service"],ex:"Une étape ; plus lente pour les commandes volumineuses.",ref:"Leçon 11.3.3.3"},
{k:"case",s:"Trois préparateurs traitent en même temps différentes parties d’une commande, puis regroupent les articles.",q:"Quelle organisation est appliquée ?",a:["La préparation en parallèle (deux étapes)","La préparation en série (une étape)","Le prélèvement orienté commande seul","La préparation statique en secteur unique"],ex:"Réduit les délais des commandes à nombreuses lignes.",ref:"Leçon 11.3.3.3"},
{k:"qcm",q:"Qu’est-ce que le procédé Pick-and-Pack ?",a:["Prélever et emballer les articles en une seule opération","Prélever les articles puis les stocker de nouveau","Emballer les articles avant leur réception","Prélever les articles sans jamais les emballer"],ex:"Directement dans l’emballage d’expédition.",ref:"Leçon 11.3.3.4"},
{k:"multi",q:"Dans quelles conditions le Pick-and-Pack est-il idéal ?",good:["Produits simples ou déjà emballés","Emballages standardisés","Peu d’articles à emballer différemment"],bad:["Produits très fragiles","Emballages faits sur mesure"],ex:"Conditions idéales et limites.",ref:"Leçon 11.3.3.4"},
{k:"case",s:"Une boutique en ligne de verrerie fine veut appliquer le Pick-and-Pack à tous ses envois.",q:"Que lui conseillez-vous ?",a:["C’est déconseillé : les produits fragiles exigent un emballage spécifique","C’est parfait : le Pick-and-Pack convient surtout aux produits fragiles","C’est obligatoire pour tous les produits en verre envoyés par la poste","C’est sans importance, l’emballage n’a aucun effet sur la casse"],ex:"Limite du Pick-and-Pack.",ref:"Leçon 11.3.3.4"},
{k:"case",s:"Le terminal indique en temps réel au préparateur l’emplacement suivant, dans l’ordre du parcours.",q:"Comment le flux d’informations soutient-il le flux de matériel ?",a:["Il réduit les trajets inutiles et les erreurs de prélèvement","Il supprime le besoin de prélever physiquement les articles","Il augmente le nombre de trajets pour chaque commande","Il remplace l’organisation par zones de l’entrepôt"],ex:"Interaction entre les domaines.",ref:"Leçons 11.3.1 et 11.3.2"},
{k:"case",s:"Un entrepôt dispose de convoyeurs très rapides, mais les ordres de préparation ne sont imprimés qu’une fois par jour.",q:"Quel est le point faible ?",a:["Le flux d’informations freine le flux de matériel","Le flux de matériel est trop lent pour les ordres","L’organisation par zones est trop rapide","Il n’y a aucun lien entre les trois domaines"],ex:"Un domaine faible limite la performance des autres.",ref:"Leçon 11.3"},
{k:"odd",q:"Trouvez l’intrus parmi ces éléments du flux de matériel.",a:["La saisie de la commande par téléphone","Le prélèvement manuel","Le transfert centralisé","Le déplacement unidimensionnel"],ex:"La saisie appartient au flux d’informations.",ref:"Leçon 11.3"},
{k:"tf",q:"Une organisation efficace optimise l’ensemble du système de préparation des commandes.",v:true,ex:"Elle coordonne flux de matériel et flux d’informations.",ref:"Leçon 11.3.3"}
]},
/* ============ 5 · TEMPS PARTIELS ============ */
{code:"h3.2·h3.5·h3.7", t:"Temps partiels et calculs", g:"h3.2 Je distingue les différentes activités de préparation des commandes et les affecte aux temps partiels corrects. (C3) · h3.5 J’explique les facteurs qui influencent le temps de traitement d’une préparation de commandes. (C3) · h3.7 Je calcule le pourcentage des temps partiels par rapport au temps total de préparation des commandes, j’interprète les résultats et je propose des possibilités d’optimisation. (C4)", col:"amber", ic:"clock",
ch:[
{k:"multi",q:"Quels sont les cinq temps partiels de la préparation des commandes ?",good:["Le temps d’organisation","Le temps de déplacement","Le temps de prélèvement","Le temps mort","Le temps perdu"],bad:["Le temps de livraison","Le temps de fabrication"],ex:"Ensemble, ils font 100 %.",ref:"Leçon 11.5"},
{k:"sort",q:"Classez ces activités dans le bon temps partiel.",c:["Organisation","Déplacement","Prélèvement","Temps mort"],it:[["Trier les documents",0],["Préparer le chariot",0],["Marcher entre deux emplacements",1],["Saisir et déposer l’article",2],["Retirer un suremballage",3],["Compter les pièces",3]],ex:"Affectation aux temps partiels.",ref:"Leçon 11.5"},
{k:"tf",q:"Les cinq temps partiels représentent ensemble 100 % du temps de préparation.",v:true,ex:"Leur répartition varie selon l’entreprise.",ref:"Leçon 11.5"},
{k:"qcm",q:"Que comprend le temps de prélèvement ?",a:["La prise de l’article et son dépôt dans le contenant","La marche entre deux emplacements de stockage","Le tri des documents avant de commencer","Les pauses et les discussions entre collègues"],ex:"Répété des centaines de fois par jour.",ref:"Leçon 11.5.3"},
{k:"tf",q:"Le temps mort regroupe des activités inutiles qu’il faut supprimer complètement.",v:false,ex:"Ce sont des activités secondaires mais indispensables.",ref:"Leçon 11.5.4"},
{k:"case",s:"Un préparateur attend 10 minutes que le transport interne lui apporte des bacs vides.",q:"À quel temps partiel cela correspond-il ?",a:["Le temps perdu (lié au matériel)","Le temps de prélèvement de l’article","Le temps d’organisation du travail","Le temps de déplacement entre deux points"],ex:"Attente de transport ou d’informations.",ref:"Leçon 11.5.5"},
{k:"case",s:"Un préparateur lit et vérifie ses documents, ouvre un colis, puis enregistre une quantité manquante.",q:"À quel temps partiel cela correspond-il ?",a:["Le temps mort","Le temps perdu","Le temps de déplacement","Le temps de prélèvement"],ex:"Activités secondaires indispensables.",ref:"Leçon 11.5.4"},
{k:"case",s:"Après sa tournée, le préparateur dépose ses bacs au point de collecte et range son scanner.",q:"À quel temps partiel cela correspond-il ?",a:["Le temps d’organisation","Le temps mort des activités secondaires","Le temps perdu en attente de matériel","Le temps de prélèvement des articles"],ex:"Tâches avant et après le prélèvement.",ref:"Leçon 11.5.1"},
{k:"match",q:"Associez chaque temps partiel à une mesure d’optimisation.",p:[["Temps de déplacement","Articles à forte rotation près de l’entrée"],["Temps de prélèvement","Hauteur ergonomique"],["Temps mort","Balance de comptage"],["Temps perdu","Horaires variables et primes"]],ex:"Optimisations possibles.",ref:"Leçon 11.5"},
{k:"case",s:"Un préparateur compte à la main 500 vis pour chaque commande.",q:"Comment réduire ce temps mort ?",a:["Utiliser une balance de comptage","Compter deux fois pour être sûr","Faire recompter par un second préparateur","Supprimer la quantité de la liste"],ex:"Automatiser le comptage.",ref:"Leçon 11.5.4"},
{k:"num",q:"Sur 60 minutes de préparation, le déplacement dure 30 minutes. Quelle part représente-t-il, en % ?",n:50,tol:0,u:"%",ex:"30 ÷ 60 × 100 = 50 %.",ref:"Leçon 11.5"},
{k:"num",q:"Temps total : 200 min (organisation 20, déplacement 90, prélèvement 50, temps mort 30, temps perdu 10). Quelle est la part du déplacement, en % ?",n:45,tol:0,u:"%",ex:"90 ÷ 200 × 100 = 45 %.",ref:"Leçon 11.5"},
{k:"num",q:"Avec les mêmes données (200 min au total, prélèvement 50 min), quelle est la part du prélèvement, en % ?",n:25,tol:0,u:"%",ex:"50 ÷ 200 × 100 = 25 %.",ref:"Leçon 11.5"},
{k:"case",s:"Votre analyse montre que le déplacement représente 45 % du temps total de préparation.",q:"Quelle mesure est prioritaire ?",a:["Rapprocher les articles A de l’entrée et optimiser l’itinéraire","Acheter des cartons plus grands pour l’expédition","Augmenter le nombre de documents imprimés par commande","Allonger les allées pour mieux répartir les articles"],ex:"Le temps partiel le plus élevé est la cible prioritaire.",ref:"Leçons 11.5.2 et 11.3.3.5"},
{k:"case",s:"Dans votre équipe, le temps perdu atteint 25 % du temps total.",q:"Quelles mesures proposez-vous ?",a:["Améliorer l’ambiance, la motivation et l’organisation des pauses","Ajouter des contrôles visuels à chaque article prélevé","Réduire la hauteur des rayonnages de toute la zone","Imprimer les listes de prélèvement en double exemplaire"],ex:"Optimisation du temps perdu.",ref:"Leçon 11.5.5"},
{k:"num",q:"Le prélèvement dure 12 s par position et représente 20 % du temps total. Quel est le temps total par position, en secondes ?",n:60,tol:0,u:"s",ex:"12 ÷ 20 × 100 = 60 s.",ref:"Leçon 11.6.2"},
{k:"num",q:"Avec 60 s par position et 1 800 positions par jour, combien d’heures de préparation faut-il ?",n:30,tol:0,u:"h",ex:"60 × 1 800 = 108 000 s = 30 h.",ref:"Leçon 11.6.2"},
{k:"num",q:"Il faut 30 h de préparation par jour et un préparateur travaille 8 h. Combien de préparateurs faut-il (arrondi au supérieur) ?",n:4,tol:0,u:"préparateurs",ex:"30 ÷ 8 = 3,75 → 4.",ref:"Leçon 11.6.2"},
{k:"num",q:"Une préparatrice met 80 s par position. Quelle est sa capacité horaire, en positions ?",n:45,tol:0,u:"positions",ex:"3 600 ÷ 80 = 45.",ref:"Leçon 11.6.2"},
{k:"num",q:"Le prélèvement dure 18 s et représente 20 % du temps total. Combien de positions peut-on préparer en 8 h ?",n:320,tol:0,u:"positions",ex:"18 ÷ 20 × 100 = 90 s ; 28 800 ÷ 90 = 320.",ref:"Leçon 11.6.2"},
{k:"num",q:"Les coûts d’exploitation sont de 102 CHF par heure pour 51 positions par heure. Quel est le coût par position, en CHF ?",n:2,tol:0,u:"CHF",ex:"102 ÷ 51 = 2 CHF.",ref:"Leçon 11.6.2"},
{k:"case",s:"Une entreprise relève 120 erreurs de préparation sur 92 000 prélèvements dans l’année.",q:"Quel est son taux d’erreur ?",a:["Environ 0,13 % des lignes","Environ 1,30 % des lignes","Environ 13,0 % des lignes","Environ 0,013 % des lignes"],ex:"120 ÷ 92 000 × 100 = 0,13 %.",ref:"Leçon 11.6.2"},
{k:"case",s:"Un opérateur met en moyenne 85 secondes par position.",q:"Quelle est sa capacité horaire ?",a:["Environ 42 positions par heure","Environ 85 positions par heure","Environ 36 positions par heure","Environ 24 positions par heure"],ex:"3 600 ÷ 85 = 42,35.",ref:"Leçon 11.6.2"},
{k:"order",q:"Remettez dans l’ordre le calcul du nombre de préparateurs nécessaires.",a:["Calculer le temps total par position","Multiplier par le nombre de positions","Convertir le total en heures","Diviser par le temps de travail journalier","Arrondir au nombre entier supérieur"],ex:"Exemple 1 de la leçon 11.6.2.",ref:"Leçon 11.6.2"},
{k:"multi",q:"Quels facteurs liés à la structure de la commande influencent le temps de traitement ?",good:["Le nombre de positions","Les unités par position","Le volume de la commande","Le mode d’expédition"],bad:["La couleur du logo du client","Le jour de naissance du préparateur"],ex:"Structure de la commande.",ref:"Leçon 11.6.1"},
{k:"sort",q:"Classez ces facteurs.",c:["Structure de la commande","Structure des articles","Structure d’accès"],it:[["Nombre de positions",0],["Volume de la commande",0],["Poids",1],["Taux de rotation",1],["Type de rayonnage",2],["Méthode de préparation",2]],ex:"Trois familles de facteurs.",ref:"Leçon 11.6.1"},
{k:"sort",q:"Ces facteurs sont-ils statiques ou dynamiques ?",c:["Facteur statique","Facteur dynamique"],it:[["Répartition ABC",0],["Stock moyen",0],["Taille et poids des articles",0],["Nombre de commandes par jour",1],["Flux d’entrées et de sorties",1],["Transferts de stock",1]],ex:"Statiques : structure ; dynamiques : activité quotidienne.",ref:"Leçon 11.6.1"},
{k:"case",s:"En fin de mois, le nombre de commandes double et elles concernent surtout des articles lourds stockés en hauteur.",q:"Quel est l’effet combiné sur le temps de traitement ?",a:["Il augmente fortement, car plusieurs facteurs s’additionnent","Il diminue, car les articles lourds se prélèvent plus vite","Il reste identique, la hauteur n’a aucune influence","Il diminue, car les commandes sont plus nombreuses"],ex:"Facteurs dynamiques et structure des articles combinés.",ref:"Leçon 11.6.1"},
{k:"case",s:"Vous comparez le prélèvement d’un article lourd et encombrant et celui d’un petit article léger.",q:"Lequel demande le plus de temps ?",a:["L’article lourd et encombrant","Le petit article léger","Les deux exactement le même","Aucun, le poids ne compte pas"],ex:"Exemple de facteur statique.",ref:"Leçon 11.6.1"},
{k:"odd",q:"Trouvez l’intrus parmi ces temps partiels.",a:["Le temps de livraison au client","Le temps d’organisation","Le temps de déplacement","Le temps mort"],ex:"La livraison ne fait pas partie des cinq temps partiels de la préparation.",ref:"Leçon 11.5"},
{k:"qcm",q:"Que mesure le taux de service ?",a:["Le pourcentage de commandes livrées complètes dans les délais","Le nombre de pauses prises chaque jour par les préparateurs","Le temps passé à ranger le matériel après chaque tournée","Le coût d’achat moyen des articles stockés dans l’entrepôt"],ex:"KPI de préparation.",ref:"Leçon 11.6.1"}
]},
/* ============ 6 · OPTIMISATION ET SÉCURITÉ ============ */
{code:"h3.6·h3.8·h3.11", t:"Trajets, points faibles et sécurité", g:"h3.6 Je montre à l’aide d’études de cas les possibilités de raccourcir les trajets et les temps de préparation de commandes. (C3) · h3.8 J’identifie les points faibles du flux de données et de l’organisation et décris les mesures d’amélioration dans la préparation des commandes. (C4) · h3.11 Je décris les risques et les dangers dans la préparation des commandes et les mesures d’amélioration de la protection de la santé et de l’environnement, de l’ergonomie et de la sécurité au travail. (C3)", col:"emerald", ic:"safe",
ch:[
{k:"qcm",q:"Dans la préparation par allée de prélèvement, où placer les articles à forte rotation (A) ?",a:["Près de l’allée principale","Au fond des allées secondaires","Au dernier niveau du rayonnage","Dans un entrepôt séparé"],ex:"Grâce à une analyse ABC.",ref:"Leçon 11.3.3.5"},
{k:"fill",q:"Une analyse ___ permet d’identifier les articles les plus commandés.",a:["ABC","LIFO","SWOT","MOP"],ex:"Pour mieux organiser l’entrepôt.",ref:"Leçon 11.3.3.5"},
{k:"case",s:"Les cartons de papier pour imprimante sont les articles les plus demandés de l’entrepôt.",q:"Où les placez-vous ?",a:["Près de l’entrée principale de la zone de stockage","Au fond de la dernière allée, loin de l’expédition","En hauteur, au dernier niveau des rayonnages","Dans une réserve externe, à quelques kilomètres"],ex:"Articles A près de l’allée principale.",ref:"Leçon 11.3.3.5"},
{k:"qcm",q:"Qu’est-ce que la préparation MOP (Multi Order Picking) ?",a:["Un seul tour pour plusieurs petites commandes, un bac par commande","Un tour séparé pour chaque article de chaque commande client","Une préparation réservée aux grosses commandes sur palette","Un contrôle total de chaque article par deux personnes"],ex:"Réduit les temps de déplacement.",ref:"Leçon 11.3.3.5"},
{k:"case",s:"Une préparatrice doit préparer 5 petites commandes dans le même entrepôt.",q:"Comment raccourcir ses trajets ?",a:["Utiliser le MOP avec un bac par commande sur son chariot","Faire cinq tours complets, un pour chaque commande","Attendre le lendemain pour regrouper avec d’autres","Préparer chaque commande dans un entrepôt différent"],ex:"Un seul trajet pour 5 commandes.",ref:"Leçon 11.3.3.5"},
{k:"tf",q:"Dans la préparation sérielle, le préparateur parcourt toutes les allées de rayonnages.",v:true,ex:"Utilisée quand l’entrepôt n’est pas divisé en zones.",ref:"Leçon 11.3.3.5"},
{k:"case",s:"L’ordre des lignes sur la liste oblige le préparateur à revenir trois fois dans la même allée.",q:"Quelle amélioration proposez-vous ?",a:["Trier les lignes selon un itinéraire logique","Ajouter des lignes vides entre les articles","Imprimer la liste dans l’ordre alphabétique","Laisser chaque préparateur choisir au hasard"],ex:"Ordre de prélèvement logique et optimisé.",ref:"Leçon 11.5.2"},
{k:"multi",q:"Quelles sont les erreurs de préparation les plus fréquentes ?",good:["Une quantité incorrecte","Un mauvais article prélevé","Une mauvaise unité (pièce au lieu de paquet)"],bad:["Une commande livrée à l’heure","Un carton correctement fermé"],ex:"Erreurs fréquentes.",ref:"Leçon 11.2.1"},
{k:"sort",q:"Classez ces causes d’erreurs.",c:["Cause humaine","Cause organisationnelle"],it:[["Manque de concentration",0],["Manque de motivation",0],["Manque de connaissances des processus",0],["Ordres incomplets ou peu clairs",1],["Emplacements sans étiquette",1],["Panne d’un scanner",1]],ex:"Causes des erreurs.",ref:"Leçon 11.2.2"},
{k:"case",s:"Plusieurs erreurs proviennent d’emplacements de stockage qui n’ont pas d’étiquette.",q:"Quelle mesure d’amélioration proposez-vous ?",a:["Étiqueter clairement chaque emplacement","Demander aux préparateurs de deviner","Supprimer les adresses des listes","Augmenter la vitesse de prélèvement"],ex:"Point faible organisationnel : stock mal organisé.",ref:"Leçon 11.2.2"},
{k:"case",s:"Les listes de préparation sont mal imprimées et les références sont difficiles à lire.",q:"Quel point faible du flux de données identifiez-vous ?",a:["Des documents peu clairs, à remplacer par des supports lisibles ou numériques","Des préparateurs trop rapides, qu’il faut ralentir pendant la tournée","Un rayonnage trop haut, qu’il faut remplacer par des étagères basses","Une organisation par zones, qu’il faut supprimer dans tout l’entrepôt"],ex:"Documents clairs, préparation sans papier.",ref:"Leçons 11.2.4 et 11.5.4"},
{k:"case",s:"Un nouvel intérimaire fait beaucoup d’erreurs, car il ne connaît pas les processus de l’entrepôt.",q:"Que proposez-vous ?",a:["Le former avant de lui confier des commandes","Le laisser apprendre seul de ses erreurs","Lui confier les commandes les plus urgentes","Supprimer les contrôles pour qu’il aille vite"],ex:"Formation régulière du personnel.",ref:"Leçons 11.2.2 et 11.2.4"},
{k:"multi",q:"Quelles conséquences une commande mal préparée peut-elle avoir ?",good:["Des coûts supplémentaires (retour, livraison express)","Une perte d’image auprès du client","Un risque de perte de clientèle"],bad:["Une hausse automatique des ventes","Une baisse des frais de transport"],ex:"Conséquences des erreurs.",ref:"Leçon 11.2.3"},
{k:"match",q:"Associez chaque méthode de contrôle à sa caractéristique.",p:[["Contrôle total","Chaque article : fiable mais long"],["Échantillonnage","Une partie : rapide mais moins précis"],["Contrôle visuel","Coup d’œil : rapide mais peu fiable"]],ex:"Comment effectuer le contrôle.",ref:"Leçon 11.3.3.4"},
{k:"case",s:"Au poste d’expédition, une balance indique qu’un colis est plus léger que prévu.",q:"Que signifie cette alerte ?",a:["Un article est probablement manquant","Le colis est parfaitement conforme","La balance doit être jetée aussitôt","Le client a annulé sa commande"],ex:"Comparaison avec le poids attendu.",ref:"Leçon 11.3.3.4"},
{k:"case",s:"Un préparateur expérimenté ne repère pas ses propres oublis lorsqu’il contrôle ses commandes.",q:"Quelle mesure proposez-vous ?",a:["Faire contrôler par une autre personne (double regard)","Supprimer complètement le contrôle pour gagner du temps","Remplacer le contrôle total par un simple coup d’œil rapide","Lui demander de contrôler encore plus vite ses commandes"],ex:"Le double regard attrape plus facilement les oublis.",ref:"Leçon 11.3.3.4"},
{k:"order",q:"Remettez dans l’ordre les moments possibles du contrôle.",a:["Juste après le prélèvement","Avant l’emballage","Après l’emballage, avant l’expédition"],ex:"Quand effectuer le contrôle.",ref:"Leçon 11.3.3.4"},
{k:"odd",q:"Trouvez l’intrus parmi ces mesures pour éviter les erreurs.",a:["Supprimer tous les contrôles","Former régulièrement le personnel","Instaurer un double contrôle","Préparer sans papier"],ex:"Mesures de la leçon 11.2.4.",ref:"Leçon 11.2.4"},
{k:"tf",q:"Une bonne ambiance de travail contribue à éviter les erreurs de préparation.",v:true,ex:"Motivation et responsabilité.",ref:"Leçon 11.2.4"},
{k:"multi",q:"Quels risques courants trouve-t-on en préparation de commandes ?",good:["La manutention de charges lourdes","La collision avec un chariot élévateur","La chute d’objets depuis les rayonnages","Le trébuchement sur des obstacles"],bad:["Un excès de pauses réglementaires","Une température de bureau trop agréable"],ex:"Risques et dangers.",ref:HS_PC},
{k:"case",s:"Un préparateur soulève un carton de 20 kg posé au sol en pliant le dos, jambes tendues.",q:"Quel geste lui montrez-vous ?",a:["Plier les jambes, garder le dos droit et la charge près du corps","Garder les jambes tendues et tirer le carton d’un coup sec vers le haut","Soulever le carton en tournant le buste pour aller plus vite au chariot","Lever le carton à bout de bras, le plus loin possible du corps et du dos"],ex:"Principes de base du port de charges.",ref:HS_PC},
{k:"case",s:"Les articles les plus lourds et les plus demandés sont stockés au ras du sol et au-dessus de la tête.",q:"Quelle amélioration ergonomique proposez-vous ?",a:["Les placer à hauteur de taille, entre les genoux et les épaules","Les placer encore plus haut pour libérer de la place au sol","Les laisser ainsi, car la hauteur de stockage n’a aucun effet","Les stocker en profondeur, derrière d’autres articles plus légers"],ex:"Hauteur ergonomique : optimise le prélèvement et ménage le dos.",ref:"Leçon 11.5.3 · "+HS_PC},
{k:"multi",q:"Quels équipements de protection individuelle sont adaptés en préparation de commandes ?",good:["Des chaussures de sécurité","Des gants de protection","Un gilet à haute visibilité"],bad:["Des sandales ouvertes","Des écouteurs avec musique forte"],ex:"Selon les risques du poste.",ref:HS_PC},
{k:"case",s:"Un apprenti veut conduire un chariot élévateur pour gagner du temps, sans avoir suivi de formation.",q:"Que lui dites-vous ?",a:["Il doit d’abord suivre une formation de cariste reconnue","Il peut conduire s’il roule plus lentement que les autres","Il peut conduire s’il a le permis de voiture","Il peut conduire si un collègue lui explique en deux minutes"],ex:"La conduite de chariots élévateurs exige une formation (directive CFST 6518).",ref:HS_PC},
{k:"case",s:"Dans un grand entrepôt en préparation statique, les opérateurs sont épuisés en fin de journée.",q:"Quelle mesure améliore à la fois la santé et la performance ?",a:["Réduire les trajets : zones, articles A proches ou marchandise vers personne","Allonger les journées pour répartir la fatigue sur plus d’heures","Supprimer les pauses pour terminer plus tôt la journée de travail","Ajouter des contrôles visuels à chaque passage dans les allées"],ex:"Moins de déplacements = moins de fatigue.",ref:"Leçons 11.3.2.1 et 11.5.2"},
{k:"case",s:"Des palettes vides et des films plastiques encombrent les allées de prélèvement.",q:"Quel risque et quelle mesure retenez-vous ?",a:["Risque de chute et de collision : dégager les allées et trier les déchets","Aucun risque : les allées encombrées ralentissent seulement le travail","Risque d’incendie uniquement : il suffit d’ouvrir les fenêtres","Risque pour le client seulement : il faut prévenir le transporteur"],ex:"Sécurité et environnement (recyclage des emballages).",ref:HS_PC},
{k:"tf",q:"Le Pick-by-Voice permet au préparateur de garder les mains libres et le regard sur son chemin.",v:true,ex:"Instructions vocales : ergonomie et sécurité.",ref:"Leçon 11.3.1.2 · "+HS_PC}
]}
];

